data=[]
for src in sources:
    i=src['reviewer'];items=[]
    for n,comment in enumerate(src['paragraphs'][2:],1):
        cid=f'R{i}.{n}';change_ids=[p['id'] for p in m['patches'] if cid in p['ids']]
        assert change_ids,cid
        items.append({'id':cid,'comment':comment,'response':responses[cid],'changes':change_ids})
    assert len(items)==7
    data.append({'reviewer':i,'title':src['paragraphs'][0],'overview':src['paragraphs'][1],'items':items})
(WORK/'responses.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print('Prepared 21 responses with verified change mappings.')
